import yaml
import os

# ------------------------------------ public API ---------------


class EmptyConfiguration(Exception):
    pass


def get_emssim_rpcserver_host_port(for_enb=1):
    """
    Gets host and port of RPC server from env yaml.

    :param for_enb: enb number (1 or 2)
    :return: tuple(host ip, port number)

    +--------------------------------------------------------------+
    |              Examples                                        |
    +==============================================================+
    | ${rpc_host}  ${rpc_port}=  get_emssim_rpcserver_host_port  1 |
    +--------------------------------------------------------------+
    """
    port_key = 'EMSSIM_RPC_PORT_%d' % for_enb
    env = _get_env_config()
    if port_key not in env:
        err = "%s for enb=%d not defined inside %s" % (port_key, for_enb, _env_config_filename())
        raise KeyError(err)
    return env['EMSSIM_IP'], env[port_key]


def get_emssim_cliserver_host_port(for_enb=1):
    """
    Gets host and port of EMSSIM CLI server from env yaml.

    :param for_enb: enb number (1 or 2)
    :return: tuple(host ip, port number)

    +--------------------------------------------------------------+
    |              Examples                                        |
    +==============================================================+
    | ${cli_host}  ${cli_port}=  get_emssim_cliserver_host_port  1 |
    +--------------------------------------------------------------+
    """
    port_key = 'EMSSIM_CLI_PORT_%d' % for_enb
    env = _get_env_config()
    if port_key not in env:
        err = "%s for enb=%d not defined inside %s" % (port_key, for_enb, _env_config_filename())
        raise KeyError(err)
    return env['EMSSIM_IP'], env[port_key]


# ------------------------ Implementation ----------------------------------------


_cached_env = {}


def _get_env_config():
    global _cached_env
    if not _cached_env:
        _cached_env = _read_env_config(_env_config_filename())
    return _cached_env


def _env_config_filename():
    env_filename = os.getenv("ENV_CONFIG")
    if not env_filename:
        env_filename = os.path.join(os.getenv("HOME"), "config", "env.yaml")
    return env_filename


def _read_env_config(env_filename):
    with open(env_filename) as env_file:
        env_file_content = env_file.read()
        env = yaml.load(env_file_content, Loader=yaml.Loader)
        if not env:
            err = "%s is empty" % env_filename
            raise EmptyConfiguration(err)
        return env


if __name__ == '__main__':
    print("Single ENB configuration")
    print("    EMSSIM RPC server at: %s:%d" % get_emssim_rpcserver_host_port())
    print("    EMSSIM CLI server at: %s:%d" % get_emssim_cliserver_host_port())

    print("Handover configuration")
    print("  Source ENB:")
    print("    EMSSIM RPC server at: %s:%d" % get_emssim_rpcserver_host_port(for_enb=1))
    print("    EMSSIM CLI server at: %s:%d" % get_emssim_cliserver_host_port(for_enb=1))
    print("  Target ENB:")
    print("    EMSSIM RPC server at: %s:%d" % get_emssim_rpcserver_host_port(for_enb=2))
    print("    EMSSIM CLI server at: %s:%d" % get_emssim_cliserver_host_port(for_enb=2))
